async def act(page):
    """
    From the current Manage Attributes page, open the Size attribute edit page (deterministic navigation),
    add two option rows for sizes '30' and '31', fill them, and save the attribute.

    Notes:
    - There are no knowledge-base helper functions available; all interactions use Playwright locators directly.
    - When navigating by clicking a link that takes us away, use page.goto(href) after reading the href so clicks that navigate
      are not performed prematurely.
    - The final action is clicking Save, which will navigate away from the edit page.
    """
    import asyncio

    async def short_wait():
        await asyncio.sleep(0.4)

    # 1) Get deterministic edit href for 'Size' attribute
    try:
        size_link = page.get_by_role("link", name="Size")
        if await size_link.count() > 0:
            href = await size_link.first.get_attribute("href")
        else:
            href = None
    except Exception:
        href = None

    # 1b) Fallback: search rows for 'Size' and extract a link from the row
    if not href:
        try:
            # prefer the table that has the 'Attribute Label' header
            table = page.get_by_role("table").filter(has=page.get_by_role("link", name="Attribute Label")).first
            rows = table.get_by_role("row")
            rc = await rows.count()
            href = None
            for i in range(rc):
                try:
                    r = rows.nth(i)
                    if await r.get_by_text("Size", exact=False).count() > 0:
                        links_in_row = r.get_by_role("link")
                        if await links_in_row.count() > 0:
                            href = await links_in_row.first.get_attribute("href")
                            if href:
                                break
                except Exception:
                    continue
        except Exception:
            href = None

    if not href:
        # Can't deterministically open the Size edit page; abort
        return

    # 2) Navigate to the Size attribute edit page (deterministic navigation)
    try:
        await page.goto(href)
        await page.wait_for_load_state("networkidle")
        await short_wait()
    except Exception:
        return

    # 3) Reveal Manage Label / Options tab if present
    try:
        tab = page.get_by_role("link", name="Manage Label / Options")
        if await tab.count() > 0:
            await tab.first.click()
            await short_wait()
    except Exception:
        pass

    # 4) Add two option rows by clicking an 'Add' button (try common labels, then scan buttons)
    added = False
    try:
        candidates = ["Add Option", "Add New Option", "Add New", "Add"]
        for candidate in candidates:
            try:
                btn = page.get_by_role("button", name=candidate)
                if await btn.count() > 0:
                    await btn.first.click()
                    await short_wait()
                    await btn.first.click()
                    await short_wait()
                    added = True
                    break
            except Exception:
                continue

        if not added:
            buttons = page.get_by_role("button")
            bcount = await buttons.count()
            for i in range(bcount):
                try:
                    b = buttons.nth(i)
                    txt = ""
                    try:
                        txt = (await b.inner_text()).strip().lower()
                    except Exception:
                        txt = ""
                    if 'add' in txt:
                        await b.click()
                        await short_wait()
                        await b.click()
                        await short_wait()
                        added = True
                        break
                except Exception:
                    continue
    except Exception:
        added = False

    # 5) Fill two empty visible textboxes with '30' and '31'
    try:
        textboxes = page.get_by_role('textbox')
        tb_count = await textboxes.count()
        filled = 0
        for i in range(tb_count):
            if filled >= 2:
                break
            try:
                tb = textboxes.nth(i)
                if not await tb.is_visible():
                    continue
                val = ''
                try:
                    val = (await tb.input_value()).strip()
                except Exception:
                    try:
                        val = (await tb.inner_text()).strip()
                    except Exception:
                        val = ''
                if val == '':
                    if filled == 0:
                        await tb.fill('30')
                        filled += 1
                    elif filled == 1:
                        await tb.fill('31')
                        filled += 1
            except Exception:
                continue

        # fallback: fill last two visible textboxes if needed
        if filled < 2:
            visible_idxs = []
            for i in range(tb_count):
                try:
                    tb = textboxes.nth(i)
                    if await tb.is_visible():
                        visible_idxs.append(i)
                except Exception:
                    continue
            if len(visible_idxs) >= 2:
                try:
                    await textboxes.nth(visible_idxs[-2]).fill('30')
                    await textboxes.nth(visible_idxs[-1]).fill('31')
                    filled = 2
                except Exception:
                    pass

        if filled < 2:
            # couldn't reliably fill both option labels; abort
            return
    except Exception:
        return

    # 6) Save the attribute (final action - will navigate away)
    try:
        save_btn = page.get_by_role('button', name='Save Attribute')
        if await save_btn.count() > 0:
            await save_btn.first.click()
            return
    except Exception:
        pass

    try:
        save_btn = page.get_by_role('button', name='Save')
        if await save_btn.count() > 0:
            await save_btn.first.click()
            return
    except Exception:
        pass

    # Last resort: click first button with 'save' in text
    try:
        buttons = page.get_by_role('button')
        bcount = await buttons.count()
        for i in range(bcount):
            try:
                b = buttons.nth(i)
                txt = ''
                try:
                    txt = (await b.inner_text()).lower()
                except Exception:
                    txt = ''
                if 'save' in txt:
                    await b.click()
                    return
            except Exception:
                continue
    except Exception:
        return

